-- A running job's words are kept until a turn of it takes them (docs/agent-control.md, 「Words for a running
-- job」): the sessions its turns started, the words said to it or noted on its item, and the newest note its
-- prompt carried.
CREATE TABLE IF NOT EXISTS "job_sessions" (
  "session_id" text NOT NULL,
  "job_id" bigint NOT NULL,
  "started_at" bigint NOT NULL,
  PRIMARY KEY ("session_id", "job_id")
);

CREATE TABLE IF NOT EXISTS "job_words" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "job_id" bigint NOT NULL,
  "text" text NOT NULL,
  "said_by" text NOT NULL,
  "note_id" bigint,
  "said_at" bigint NOT NULL,
  "handed_at" bigint,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "job_words_waiting" ON "job_words" ("job_id", "id") WHERE "handed_at" IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "job_words_notes" ON "job_words" ("job_id", "note_id") WHERE "note_id" IS NOT NULL;

ALTER TABLE "jobs" ADD COLUMN IF NOT EXISTS "notes_through" bigint;
